export const meta = {
  name: 'cycle2-verify',
  description: 'Independently re-derive Cycle-2 decision-critical numbers from raw Itapema CSVs and adversarially challenge the Morretes/coverage conclusions',
  phases: [
    { title: 'Verify', detail: 'independent re-derivation from raw CSVs' },
    { title: 'Challenge', detail: 'skeptic + strategist review of interpretation' },
  ],
}

const VERIFY = {
  type: 'object',
  properties: {
    checks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          quantity: { type: 'string' },
          my_claim: { type: 'string' },
          independent_value: { type: 'string' },
          matches: { type: 'boolean' },
          notes: { type: 'string' },
        },
        required: ['quantity', 'my_claim', 'independent_value', 'matches'],
      },
    },
    overall: { type: 'string', description: 'CONFIRMED / DISCREPANCY / MIXED with one-line reason' },
  },
  required: ['checks', 'overall'],
}

const CHALLENGE = {
  type: 'object',
  properties: {
    top_risks: { type: 'array', items: { type: 'string' } },
    strongest_alt_explanation: { type: 'string' },
    what_would_flip_the_decision: { type: 'string' },
    verdict_on_morretes_lead: { type: 'string', description: 'SOUND / FRAGILE / UNSOUND + why' },
    verdict_on_studio_untestable: { type: 'string' },
  },
  required: ['top_risks', 'strongest_alt_explanation', 'what_would_flip_the_decision', 'verdict_on_morretes_lead'],
}

const DATA = 'jovens-talentos-2026-hackathon-data-master/data'
const PY = 'PYTHONUTF8=1 .venv/Scripts/python.exe'
const common = `You are an INDEPENDENT verifier. Write your OWN short Python script (use ${PY}, path ${DATA}), read the raw CSVs directly, and compute the quantities. Read ids as str; treat "","<NA>" as NA. Do NOT read working/decision_engine.py or working/decision_engine_results.json — independence matters. Use a unique temp script name. Report the numbers you actually computed and whether they match my claims within rounding.`

phase('Verify')

const vCoverage = agent(`${common}
Re-derive the COVERAGE-BIAS comparison. covered = airbnb_listing_id present in Price_AV_Itapema.csv; population = all rows of Details_Itapema.csv. Merge Hosts_ids_Itapema.csv (drop duplicate owner_id, keep first) on owner_id for is_superhost. Compute, for covered vs uncovered Details listings: mean number_of_reviews; mean star_rating; percent is_professional=='true'; percent is_superhost=='true'; mean number_of_bedrooms.
MY CLAIMS: reviews covered 27.08 vs uncovered 3.77; star_rating covered 4.79 vs uncovered 2.70; professional covered 18.9% vs uncovered 5.8%; superhost covered 43.4% vs uncovered 13.3%; bedrooms covered 2.45 vs uncovered 2.52. Confirm or refute each.`,
  { label: 'verify:coverage', phase: 'Verify', agentType: 'general-purpose', schema: VERIFY })

const vMethodB = agent(`${common}
Re-derive Method B ABSORPTION. In Price_AV, capture_day = date(aquisition_date), stay = date(date). For a pair (early,late): keep listings present in BOTH capture_days; keep stay dates in [max(min stay of each), min(max stay of each)]; among (listing,stay) pairs present in early, absorbed = those ABSENT in late; rate = absorbed/present_early. Compute for pair (2025-01-06, 2025-01-07) and pair (2025-01-06, 2025-01-20). Also give per-day rate = rate/gap_days.
MY CLAIMS: 06->07 gap 1 day: absorption 1.97% (~632/32121), per-day 1.97%. 06->20 gap 14 days: absorption 14.2% (~4352/30680), per-day ~1.01%. The KEY point I claim: the 1-day per-day rate (1.97%) is HIGHER than the 14-day per-day rate (1.01%), implying calendar churn contaminates the booking signal. Confirm the numbers and state whether the 1-day per-day rate indeed exceeds the 14-day per-day rate.`,
  { label: 'verify:methodB', phase: 'Verify', agentType: 'general-purpose', schema: VERIFY })

const vAirbnb = agent(`${common}
Re-derive Method A ADR per segment. In Price_AV, per airbnb_listing_id compute adr_med = median(price) over all its rows. Join to Details (listing_type=='apartamento') and Mesh (suburb). Normalize suburb: NFKD strip accents, lowercase, strip; canonical = 'Meia Praia' if contains 'meia praia', 'Centro' if =='centro', 'Morretes' if contains 'morretes'. bed = number_of_bedrooms (integer, clip at 4). Segment ADR = median of adr_med over listings that appear in Price_AV. Also report count of such listings (airbnb_priced).
MY CLAIMS (ADR median R$, n): Morretes 2q = 498, n=51; Morretes 3q = 635, n=10; Centro 1q = 450, n=78; Centro 2q = 580, n=65; Centro 3q = 790, n=45; Meia Praia 3q = 700, n=327; Meia Praia 4q = 1200, n=65. Confirm or refute each value and n.`,
  { label: 'verify:airbnb-adr', phase: 'Verify', agentType: 'general-purpose', schema: VERIFY })

const vViva = agent(`${common}
Re-derive VivaReal validity + segment medians. VivaReal_Itapema.csv: dedup by listing_id keep first. Restrict listing_type=='apartamento'. Normalize suburb same canonical rules ('Meia Praia','Centro','Morretes' plus 'Tabuleiro' if contains 'tabuleiro' or 'taboleiro'). ppm2 = sale_price/usable_area. Mark INVALID if usable_area<=0 or >1000, or ppm2<1000 or >60000, or sale_price<50000. bed=bedrooms clip 4. Segment median sale_price over VALID rows, and valid count.
MY CLAIMS (median sale_price R$, valid n): Morretes 2q = 790000, n=1035; Morretes 3q = 845000, n=155; Centro 1q = 890000, n=21; Centro 2q = 1150000, n=87; Centro 3q = 2100000, n=431; Meia Praia 3q = 1882459, n=1658. ALSO: after dedup total rows should be 8293; apartamento valid ~7391; Centro-1q valid=21 with median area ~42 m2 and one implausible 625 m2 '1-bedroom'. Confirm/refute, and comment on whether Centro-1q (n=21) is heterogeneous/thin.`,
  { label: 'verify:vivareal', phase: 'Verify', agentType: 'general-purpose', schema: VERIFY })

phase('Challenge')

const artifacts = `You may READ working/decision_engine.py and working/decision_engine_results.json and working/investment-thesis-register.md to see the full method and results. Do not run code.`

const skeptic = agent(`${artifacts}
Context: Cycle-2 window-basis (90-night) gross-yield PROXY (before all costs, hypothetical occupancy) ranks Morretes 2q as the most robust efficiency leader (rank-1 stability 65%), Centro 1q second (23%), while Meia Praia beachfront has the lowest yield. Coverage is strongly selective (covered listings: 27 vs 3.8 reviews, 43% vs 13% superhost). Method B's 1-day churn control partially fails.
Adversarially challenge: (1) Is "Morretes 2q is the efficiency leader" SOUND, FRAGILE, or UNSOUND? Consider composition confounds: are Airbnb and VivaReal Morretes 2q the same kind of unit (area/quality)? Could the low VivaReal price reflect cheaper/smaller stock, or could the ADR be inflated by coverage selection? (2) Does coverage selection bias the RELATIVE ranking, or mainly the absolute level? (3) Is the studio-Centro 'untestable' verdict correct, or is there a defensible way to test it? List the single assumption most capable of flipping the decision.`,
  { label: 'challenge:skeptic', phase: 'Challenge', agentType: 'skeptic', schema: CHALLENGE })

const strat = agent(`${artifacts}
Context as above. From an investment-committee view: is a WINDOW-basis gross-yield proxy at a hypothetical 55% occupancy a defensible decision metric to shortlist neighborhoods/profiles, given asking (not transaction) prices and ~30% missing condo/IPTU? What is the strongest ALTERNATIVE reading of these results (e.g., that absolute revenue potential or liquidity matters more than yield)? What would flip a shortlist away from Morretes toward Centro-1q or Meia Praia? Give verdict_on_morretes_lead and verdict_on_studio_untestable too.`,
  { label: 'challenge:strategist', phase: 'Challenge', agentType: 'business-strategist', schema: CHALLENGE })

const [coverage, methodB, airbnb, viva, sk, st] = await parallel([
  () => vCoverage, () => vMethodB, () => vAirbnb, () => vViva, () => skeptic, () => strat,
])

return { verify: { coverage, methodB, airbnb, viva }, challenge: { skeptic: sk, strategist: st } }
